{
  "overall_decision": "targeted_follow_up",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0001",
          "reason": "Inherited NATO custody baseline, not Erdoğan-era nuclear command or a 2022 ruler choice."
        },
        {
          "evidence_id": "E0002",
          "reason": "Preexisting CTBT ratification is structural background, not target-year conduct."
        },
        {
          "evidence_id": "E0003",
          "reason": "Preexisting NPT ratification is baseline context, not 2022 ruler action."
        },
        {
          "evidence_id": "E0004",
          "reason": "IAEA safeguards status is institutional background, not a ruler-specific 2022 decision."
        },
        {
          "evidence_id": "E0005",
          "reason": "Current IAEA country profile describes inherited civil-nuclear posture, not target-year conduct."
        },
        {
          "evidence_id": "E0011",
          "reason": "Incirlik risk context describes structural exposure, not Erdoğan's personal 2022 governance choice."
        },
        {
          "evidence_id": "E0012",
          "reason": "Alliance-technology and air-defense consequences are indirect context, not direct nuclear-risk governance."
        }
      ],
      "material_gaps": [
        {
          "gap": "No direct 2022 evidence of Erdoğan changing nuclear command, custody, or safety discipline.",
          "lenses": ["1B.3", "1B.7", "1B.9"],
          "best_source_or_query_direction": "Turkish nuclear-regulatory and presidential appointment records, IAEA or CTBTO follow-up, and contemporaneous parliamentary or cabinet records",
          "why_it_matters": "Most of the current package shows inherited posture or mediation, not a ruler-level control act."
        },
        {
          "gap": "Thin evidence on resisting proliferation by allies, proxies, or domestic factions.",
          "lenses": ["1B.6"],
          "best_source_or_query_direction": "Turkish export-control, dual-use, defense-export, and alliance-coordination records plus contemporaneous reporting",
          "why_it_matters": "This lens would better separate active restraint from baseline nonproliferation posture."
        },
        {
          "gap": "No independent follow-through record showing Zaporizhzhia mediation materially reduced risk.",
          "lenses": ["1B.1", "1B.8"],
          "best_source_or_query_direction": "UN or IAEA follow-up, official diplomatic readouts, and serious contemporaneous reporting",
          "why_it_matters": "Rhetoric and facilitation claims are weaker than verified de-escalation."
        }
      ],
      "reason": "The package is useful for baseline and a few direct 2022 civil-nuclear and mediation choices, but too much of it is inherited posture or structural context. The chapter cannot be fairly read from treaty status, custody, or IAEA pages alone, and direct ruler-specific risk-bearing choices remain thin."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package fairly presents both restraint and aggression: NATO compromise and grain-brokerage on one side, and repeated Syria escalation, proxy conduct, and civilian-harm allegations on the other. It preserves counterevidence and attribution, and the mix is sufficient to present the chapter fairly."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package is balanced enough to show the 2022 domestic-safety record: torture and detention concerns, protest suppression, press repression, stigmatizing rhetoric, and a narrow favorable counterpoint. It distinguishes allegations, official findings, and counterevidence without collapsing them into one undifferentiated abuse narrative."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package fairly covers electoral-law manipulation, media control, judicial pressure, protest restrictions, and limited favorable counterevidence. The source mix is strong and the package does not confuse formal institutions with actual contestability."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package fairly shows the core 2022 macro picture: a ruler-driven low-rate regime, severe inflation and currency depreciation, some growth and relief measures, and clear separation between policy, outcomes, and mitigation."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package fairly combines real welfare delivery and refugee-service extension with severe purchasing-power erosion and donor dependence. It does not overcredit inherited systems, and it preserves the tension between service gains and macro harm."
    },
    {
      "chapter_id": "7B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0076",
          "reason": "Unadjudicated family-linked allegation; it may be relevant context, but it is not proven personal self-dealing and should not be treated as hard integrity evidence."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct financial or beneficial-ownership evidence tying Erdoğan personally to assets, gifts, procurement, or hidden conflicts is still missing.",
          "lenses": ["7B.3", "7B.4"],
          "best_source_or_query_direction": "Asset declarations, procurement or audit records, court or inquiry findings, and high-quality investigative reporting",
          "why_it_matters": "The current package shows repeated falsehoods and network control, but not firm personal enrichment."
        },
        {
          "gap": "The Bilal Erdoğan access and lobbying allegation remains unproven.",
          "lenses": ["7B.3", "7B.4", "7B.9"],
          "best_source_or_query_direction": "Corporate records, legal filings, and investigative follow-up in Turkey or Sweden",
          "why_it_matters": "This is one of the few family-nexus items, and it needs adjudication before it can carry real weight."
        }
      ],
      "reason": "The package captures direct false economic claims, loyalist and media-control patterns, and some family-network concerns, but it still lacks hard personal financial evidence. Too much of the case rests on institutional repression rather than Erdoğan's personal honesty, conflicts of interest, or self-dealing."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package is strong: it identifies a clear program, shows implementation machinery, includes crisis management and diplomacy, and ties outcomes back to the ruler while preserving contrary macro evidence. The distinction between declared goals, execution, and results is clear enough to be fair."
    }
  ]
}
